package com.dayflow.controller;
import com.dayflow.dao.UserDAO;import com.dayflow.model.User;import com.dayflow.util.PasswordUtil;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;
@WebServlet("/settings") public class SettingsServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.getRequestDispatcher("/settings.jsp").forward(r,s);}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{User u=(User)r.getSession().getAttribute("user");UserDAO d=new UserDAO();String action=r.getParameter("action");if("profile".equals(action)){String name=r.getParameter("fullName");if(name!=null&&!name.isBlank()){d.updateName(u.getUserId(),name.trim());u.setFullName(name.trim());r.getSession().setAttribute("user",u);}}else if("password".equals(action)){String old=r.getParameter("oldPassword"),np=r.getParameter("newPassword"),cp=r.getParameter("confirmPassword");if(np==null||np.length()<8||!np.equals(cp)||!PasswordUtil.verify(old,u.getPasswordHash())){r.setAttribute("error","Password update failed. Check the current password and use matching passwords of at least 8 characters.");r.getRequestDispatcher("/settings.jsp").forward(r,s);return;}String hash=PasswordUtil.hash(np);d.updatePassword(u.getUserId(),hash);u.setPasswordHash(hash);r.getSession().setAttribute("user",u);}else if("delete".equals(action)){d.delete(u.getUserId());r.getSession().invalidate();s.sendRedirect(r.getContextPath()+"/register?deleted=1");return;}s.sendRedirect(r.getContextPath()+"/settings?saved=1");}catch(Exception e){throw new ServletException(e);}}}
